PARTITIONS = {f"2025-{m:02d}": 40 for m in range(1, 13)}
QUERY_MONTHS = ["2025-01", "2025-02", "2025-03"]

def total_gb(partitions):
    return sum(partitions.values())

def scanned_gb(partitions, wanted_months):
    wanted = set(wanted_months)
    return sum(size for month, size in partitions.items() if month in wanted)

t = total_gb(PARTITIONS)
s = scanned_gb(PARTITIONS, QUERY_MONTHS)
print(f"total_data={t}GB")
print(f"scanned_after_pruning={s}GB")
print(f"pruned_pct={round((t - s) / t * 100, 1)}%")
